entries[178530] = { ["name"] = "Kranzerang", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Wirft den Kranz einem freundlich gesinnten Spieler zu. Wenn möglich, wirft er ihn automatisch zurück.\n\"Er ist aerodynamisch und duftet nach Tannennadeln.\"\nVerkaufspreis:" }
entries[178533] = { ["name"] = "Wackelnde Haustierkiste", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Aus dem Inneren hört man ein ganz leises Knurren. Lehrt Euch, wie man den kleinen Raptor Klingeling beschwört.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)" }
