entries[178535] = { ["name"] = "Gläschen suspekter Schleim", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 30000 / 5 * 20) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\n\"Schleimig und glibberig. Hinterher ist Euch garantiert ein wenig schummrig.\"\nVerkaufspreis:" }
