entries[178540] = { ["name"] = "Schmackhafte Schmutzspeise", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 22500 / 5 * 20) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Schmutz, Larven und Glibber verschmelzen zu einer perfekten Harmonie. Ein Leckerbissen für alle Maldraxxi, die sich in der Arena gut schlagen.\"\nVerkaufspreis:" }
