entries[178543] = { ["name"] = "Gegrillte Blutwurst", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 22500 / 5 * 20) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\nVerkaufspreis:" }
entries[178544] = { ["name"] = "Dubiose Käseplatte", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 9375 / 5 * 20) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Jemand hat große Mühen auf sich genommen, um die wilden Tiere dieses Landes zu melken.\"\nVerkaufspreis:" }
