entries[178546] = { ["name"] = "Fragwürdiges Fleischprodukt", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 22500 / 5 * 20) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Dieser widerliche Fleischklumpen setzt sich aus Knochen, Sehnen und Muskeln zusammen.\"\nVerkaufspreis:" }
entries[178547] = { ["name"] = "Fragwürdiges Bratgeflügel", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 9375 / 5 * 20) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Dieses widerwärtig riechende Gericht besteht aus einer eigenen, geheimen Geflügelmischung.\"\nVerkaufspreis:" }
entries[178548] = { ["name"] = "Teeknochen", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 22500 / 5 * 20) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\nVerkaufspreis:" }
