entries[178550] = { ["name"] = "Tiefschwarzer Trüffel", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 22500 / 5 * 20) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Bluthauer graben diese Leckerbissen aus, die von Lichs und Gladiatoren gleichermaßen geschätzt werden.\"\nVerkaufspreis:" }
