entries[178553] = { ["name"] = "Schlundgebundenenschlüssel", ["text"] = "Questgegenstand\n\"Wird von den Wächtern des Tremaculums getragen.\"" }
entries[178554] = { ["name"] = "Chordy rufen", ["text"] = "Questgegenstand\nBenutzen: Ruft Chordy, falls er verschwunden oder tot ist. (10 Sek. Abklingzeit)" }
entries[178557] = { ["name"] = "Versorgungskettennotiz", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Vom Schreibtisch des Zehntherrn.\"" }
entries[178558] = { ["name"] = "Schlüssel der Quälerin", ["text"] = "Questgegenstand\n\"Mit Runen überzogen, die denen ähneln, die Anduin im Tremaculum gefangen halten.\"" }
entries[178560] = { ["name"] = "Fortschritt des Reinheitsbeitrags", ["text"] = "\"Beschreibung hier.\"" }
entries[178561] = { ["name"] = "Erinnerung des Runenmetzes", ["text"] = "Questgegenstand\n\"Eine gestohlene Erinnerung des Runenmetzes.\"" }
entries[178562] = { ["name"] = "Geschmolzene Anima", ["text"] = "Questgegenstand" }
entries[178564] = { ["name"] = "Auge des Kerkermeisters:", ["text"] = "Auge des Kerkermeisters: +1.000\n\"Erhöht eure Bedrohungsstufe bei Zovaal, dem Kerkermeister, um +1.000 Einheiten. (Diese Bedrohungsstufe wird jeden Tag auf null zurückgesetzt.) \"" }
entries[178565] = { ["name"] = "Verdächtige Nachricht", ["text"] = "Questgegenstand\n\"Zusammengeknülltes Pergament mit der feinen Kalligraphie \"DLAB TMMOK TNHEZ\".\"" }
entries[178566] = { ["name"] = "Gesprungener Handspiegel", ["text"] = "Verkaufspreis:" }
entries[178567] = { ["name"] = "Kheins Runenklinge", ["text"] = "Questgegenstand\nBenutzen: Causes an enemy to take 20% increased Physical damage for 3 Sek..\nInflicts 10 Physical damage to an enemy every 5.2 sec for 3 Sek..\nInflicts 10 Physical damage to an enemy.\n\"Runen leuchten schwach entlang dieser mitgenommenen Klinge.\"" }
entries[178568] = { ["name"] = "Beutel voller gruseliger Krabbler", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Öffnet einen Beutel voller verstörender Kreaturen, die Gegner in der Nähe 30 Sek. lang ablenken. Kann nur im Freien in den Schattenlanden verwendet werden. (1 Min Abklingzeit)\n\"Sie zappeln und fiepsen verstörend.\"\nVerkaufspreis:" }
entries[178569] = { ["name"] = "Der Ursprung des Todes", ["text"] = "Questgegenstand\n\"Ein dicker Foliant mit Theorien über die Entstehung der verflochtenen Mechanismen der Schattenlande und darüber, wie sie miteinander in Verbindung stehen.\"" }
entries[178570] = { ["name"] = "Verblassendes Erinnerungsglas", ["text"] = "Questgegenstand\n\"Dieses Erinnerungsglas scheint sehr alt zu sein und die darin enthaltenen Erinnerungen werden bald verloren gehen.\"" }
entries[178571] = { ["name"] = "Schleimige Korrespondenz", ["text"] = "Questgegenstand\n\"Ein Brief von Markgräfin Stradama an einen unbekannten Empfänger. Er wurde in einer Geheimsprache verfasst, die Ihr nicht entschlüsseln könnt.\"" }
entries[178572] = { ["name"] = "Ring aus fremdartigen Metall", ["text"] = "Questgegenstand\n\"Ein Ring aus einem merkwürdigen Metall, das Euch an Oribos erinnert.\"" }
entries[178573] = { ["name"] = "Ungewöhnliche Mechanoidenteile", ["text"] = "Questgegenstand\n\"Es scheint sich um Teile des Kerns eines Mechanoiden zu handeln, doch Ihr habt so solche wie diese noch nie in den Schattenlanden erblickt.\"" }
entries[178574] = { ["name"] = "Seltsame Ritualmaske", ["text"] = "Questgegenstand\n\"Eine Maske mit einem Robotergesicht, die nichts ähnelt, was Ihr in den Schattenlanden je gesehen habt.\"" }
entries[178575] = { ["name"] = "Goldene Energiekugel", ["text"] = "Questgegenstand\n\"Eine komplexe und komplizierte Art goldener Kugel, die etwas Düsteres in ihrem Inneren beherbergt. Gelegentlich zeigt sie ein weißes Energieflackern, das jedoch nie lange anhält.\"" }
entries[178576] = { ["name"] = "Uraltes Mittlerkopfstück", ["text"] = "Questgegenstand\n\"Das Kopfstück eines Mittlers unbekannten Ursprungs. Es unterscheidet sich deutlich von denen anderer Mittler, die Ihr in Oribos begegnet seid.\"" }
entries[178577] = { ["name"] = "Nalthors Phylakteriumanleitung", ["text"] = "Questgegenstand\n\"Eine Anleitung zur Erschaffung eines Phylakteriums, ein nekrotisches Ritual, das Lichs bei seltenen Gelegenheiten gemeinsam durchführen.\"" }
entries[178578] = { ["name"] = "Seltsame Puppe", ["text"] = "Questgegenstand\n\"Es scheint sich um ein Spielzeug oder eine Puppe zu handeln. Sie hat eine merkwürdige Form und wird wohl von einem Ort außerhalb Azeroths stammen.\"" }
entries[178579] = { ["name"] = "Stradamas verschwundenes Geschäftsbuch", ["text"] = "Questgegenstand\n\"Mehrere sorgfältig geführte Listen von Objekten und den Schleimpfützen, in denen sie gelagert werden. Hier wird ein Koordinatensystem verwendet, das Ihr noch nie gesehen habt.\"" }
entries[178580] = { ["name"] = "Münze des Champions", ["text"] = "Questgegenstand\n\"Eine merkwürdige Münze, die Champions im Theater der Schmerzen für mehrere siegreiche Runden erhalten. Hat nur zeremonielle Zwecke und keinen Nutzen als Handelsmittel.\"" }
entries[178581] = { ["name"] = "Vollgefressene Gormlarve", ["text"] = "Questgegenstand\n\"Eine weiche, zappelnde Gormlarve, die schon fast ausgewachsen zu sein scheint.\"" }
entries[178582] = { ["name"] = "Goldene Totenmaske", ["text"] = "Questgegenstand\n\"Eine Maske, die das Gesicht von Mueh'zala darstellt. Stammt vermutlich aus einer Zivilisation, die ihn einst verehrt hat.\"" }
entries[178583] = { ["name"] = "Foliant der Gräberalchemie", ["text"] = "Questgegenstand\n\"Ein Buch, das die verschiedenen Methoden zur Erschaffung und Verwendung der Gräber beschreibt.\"" }
entries[178584] = { ["name"] = "Medaillon der Orientierung", ["text"] = "Questgegenstand\n\"Ein Medaillon, mit dem man in den Schattenlanden erkennt, in welcher Richtung Oribos liegt. Wertvoll für Generäle, um ihre Armeen zu leiten, doch von absolut unschätzbarem Wert für reisende Händler.\"" }
entries[178585] = { ["name"] = "Der vergessene Schlüssel", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest." }
entries[178586] = { ["name"] = "Kyrianische Waffen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Beschwört einen Provost, um den gestohlenen Gegenstand zurückzuholen und Ruf bei den Einwohnern der Bastion zu gewinnen.\n\"Vergoldete Waffen der Einwohner der Bastion. Wie sie beschafft wurden, ist unbekannt.\"" }
entries[178587] = { ["name"] = "Maldraxxische Waffen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Beschwört einen Skelettdiener, um den gestohlenen Gegenstand zurückzuholen und Ruf bei den Einwohnern von Maldraxxus zu gewinnen.\n\"Mit Knochen versteifte Waffen der Einwohner von Maldraxxus. Wie sie beschafft wurden, ist unbekannt.\"" }
entries[178588] = { ["name"] = "Faewaffen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Beschwört eine Fee, um den gestohlenen Gegenstand zurückzuholen und Ruf bei den Einwohnern des Ardenwalds zu gewinnen.\n\"Aus Holz gefertigte Waffen der Einwohner des Ardenwalds. Wie sie beschafft wurden, ist unbekannt.\"" }
entries[178589] = { ["name"] = "Venthyrwaffen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Beschwört einen Gräber, um den gestohlenen Gegenstand zurückzuholen und Ruf bei den Einwohnern Revendreths zu gewinnen.\n\"Reich verzierte Waffen der Einwohner von Revendreth. Wie sie beschafft wurden, ist unbekannt.\"" }
entries[178590] = { ["name"] = "Sagenumwobene maldraxxische Knochenklinge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Beschwört einen Skelettdiener, um den gestohlenen Gegenstand zurückzuholen und eine große Menge Ruf bei den Einwohnern von Maldraxxus zu gewinnen.\n\"Blutgetränkt, aber unbeschadet hat diese Waffe auf den Schlachtfeldern von Maldraxxus schon Tausende Tode herbeigeführt.\"" }
entries[178591] = { ["name"] = "Uraltes Venthyrrelikt", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Beschwört einen Gräber, um den gestohlenen Gegenstand zurückzuholen und eine große Menge Ruf bei den Einwohnern Revendreths zu gewinnen.\n\"Ein uraltes Relikt der Macht, das über viele Generationen hinweg von mächtigen Venthyr weitergereicht wurde.\"" }
entries[178592] = { ["name"] = "Ehrwürdiger kyrianischer Verteidiger", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Beschwört einen Provost, um den gestohlenen Gegenstand zurückzuholen und eine große Menge Ruf bei den Einwohnern der Bastion zu gewinnen.\n\"Ein schimmerndes goldenes Zeichen des Heldentums, das in all den Jahren nur ein paar wenige Aufgestiegene erhalten haben.\"" }
entries[178593] = { ["name"] = "Aufwendiges Faehaintuch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Beschwört eine Fee, um das gestohlene Relikt zurückzuholen und eine große Menge Ruf bei den Einwohnern des Ardenwalds zu gewinnen.\n\"Über Jahrhunderte hinweg von den Sylvari verfeinert. Es strahlt es Ruhe und Anmut aus.\"" }
entries[178594] = { ["name"] = "Animagebundene Wickel", ["text"] = "Wird beim Aufheben gebunden\n\"Animagetränkte Wickel, die Knochen und Fleisch Kraft verleihen.\"\nVerkaufspreis:" }
entries[178599] = { ["name"] = "Fliegenfalle rufen", ["text"] = "Questgegenstand\nBenutzen: Ruft Fliegenfalle, falls sie verschwunden oder tot ist. (10 Sek. Abklingzeit)" }
entries[178602] = { ["name"] = "Dorniger Ring", ["text"] = "Einzigartig\nDauer: 10 min (Realzeit)\nBenutzen: Hüllt Euch für 1 Min. in Dornen, die Angreifern Naturschaden zufügen. Während Ihr in Dornen gehüllt seid, erleidet Ihr pro Sekunde Schaden.\n\"Stachelig. Wenn Ihr den ansteckt, werdet Ihr vorerst an nichts anderes denken können.\"" }
entries[178655] = { ["name"] = "Lyes Ritualpläne", ["text"] = "Questgegenstand\n\"Pläne für den Aufbau von Mor'Bitans Ritual.\"" }
entries[178656] = { ["name"] = "Xeelis Ritualpläne", ["text"] = "Questgegenstand\n\"Pläne für den Aufbau von Mor'Bitans Ritual.\"" }
entries[178657] = { ["name"] = "Halens Ritualpläne", ["text"] = "Questgegenstand\n\"Pläne für den Aufbau von Mor'Bitans Ritual.\"" }
entries[178658] = { ["name"] = "Konstrukt wiederherstellen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stellt das aktuell aktive Konstrukt wieder her, falls es verschwunden oder tot ist. Kann nur im Freien in den Schattenlanden verwendet werden. (10 Sek. Abklingzeit)\n60 ( 60)\nVerkaufspreis:" }
entries[178659] = { ["name"] = "Monströse Unterstützung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Ruft Chordy, falls er verschwunden oder tot ist. (10 Sek. Abklingzeit)\n\"Im Notfall ist jedes Konstrukt recht!\"\nVerkaufspreis:" }
entries[178662] = { ["name"] = "Unvollendete Klinge", ["text"] = "Questgegenstand\n\"Eine Klinge ohne Heft. Die in das Metall eingelassenen Runen scheinen Euch zu rufen.\"" }
entries[178663] = { ["name"] = "Kriegsbeil des sündigen Aspiranten", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Axt\n15 - 32 Schaden Geschwindigkeit 2.60\n(9.0 Schaden pro Sekunde)\n+8 Beweglichkeit\n+12 Ausdauer\nErhöht Eure kritische Trefferwertung um + 7.\n+ 9 Vielseitigkeit\nHaltbarkeit 110 / 110\nVerkaufspreis:" }
entries[178664] = { ["name"] = "Doppelbogen des sündigen Aspiranten", ["text"] = "Wird beim Aufheben gebunden\nDistanz Bogen\n31 - 42 Schaden Geschwindigkeit 3.00\n(12.2 Schaden pro Sekunde)\n+16 Beweglichkeit\n+24 Ausdauer\nErhöht Eure Tempowertung um + 13.\n+ 20 Vielseitigkeit\nHaltbarkeit 120 / 120\nVerkaufspreis:" }
entries[178665] = { ["name"] = "Reißzahn des sündigen Aspiranten", ["text"] = "Wird beim Aufheben gebunden\nEinhändig\n+8 Beweglichkeit\n+12 Ausdauer\nErhöht Eure Tempowertung um + 10.\nErhöht Eure Meisterschaftswertung um + 6.\nVerkaufspreis:" }
entries[178668] = { ["name"] = "Langspeer des sündigen Aspiranten", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stangenwaffe\n30 - 57 Schaden Geschwindigkeit 3.60\n(12.1 Schaden pro Sekunde)\n+16 Stärke\n+24 Ausdauer\nErhöht Eure kritische Trefferwertung um + 13.\n+ 20 Vielseitigkeit\nHaltbarkeit 100 / 100\nVerkaufspreis:" }
entries[178670] = { ["name"] = "Klinge des sündigen Aspiranten", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Schwert\n17 - 30 Schaden Geschwindigkeit 2.60\n(9.0 Schaden pro Sekunde)\n+8 Beweglichkeit\n+12 Ausdauer\nErhöht Eure Tempowertung um + 7.\n+ 10 Vielseitigkeit\nHaltbarkeit 110 / 110\nVerkaufspreis:" }
entries[178671] = { ["name"] = "Breitschwert des sündigen Aspiranten", ["text"] = "Wird beim Aufheben gebunden\nZweihändig\n+16 Stärke\n+54 Intelligenz\n+23 Ausdauer\nErhöht Eure Tempowertung um + 13.\nErhöht Eure Meisterschaftswertung um + 18.\nVerkaufspreis:" }
entries[178672] = { ["name"] = "Bollwerk des sündigen Aspiranten", ["text"] = "Wird beim Aufheben gebunden\nSchildhand\n+8 Stärke\n+24 Intelligenz\n+12 Ausdauer\nErhöht Eure kritische Trefferwertung um + 6.\n+ 9 Vielseitigkeit\nVerkaufspreis:" }
entries[178673] = { ["name"] = "Schildhandwaffe des sündigen Aspiranten", ["text"] = "Wird beim Aufheben gebunden\nIn Schildhand geführt\n+24 Intelligenz\n+12 Ausdauer\nErhöht Eure kritische Trefferwertung um + 9.\n+ 6 Vielseitigkeit\nVerkaufspreis:" }
entries[178674] = { ["name"] = "Gleve des sündigen Aspiranten", ["text"] = "Wird beim Aufheben gebunden\nEinhändig\n+8 Beweglichkeit\n+12 Ausdauer\n+ 6 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 9.\nVerkaufspreis:" }
entries[178675] = { ["name"] = "Traumfänger", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Versucht, einen flüchtigen Traum zu fangen.\n\"Selbst die Schattenlande haben noch eine andere Seite...\"" }
entries[178676] = { ["name"] = "Pulsierende Hautfetzen", ["text"] = "Questgegenstand\n\"Von dieser Haut tropft etwas, das Ihr Euch nur als das Blut des Landes erklären könnt.\"" }
entries[178677] = { ["name"] = "Prinz Renathal", ["text"] = "\"Mag es: Förmlich, sauber, sicher\"" }
entries[178678] = { ["name"] = "Atticus rufen", ["text"] = "Questgegenstand\nBenutzen: Ruft Atticus, falls er verschwunden oder tot ist. (10 Sek. Abklingzeit)" }
entries[178679] = { ["name"] = "Marz rufen", ["text"] = "Questgegenstand\nBenutzen: Ruft Marz, falls er verschwunden oder tot ist. (10 Sek. Abklingzeit)" }
entries[178680] = { ["name"] = "Rosenpustel rufen", ["text"] = "Questgegenstand\nBenutzen: Ruft Rosenpustel, falls sie verschwunden oder tot ist. (10 Sek. Abklingzeit)" }
entries[178681] = { ["name"] = "Schmaler Schienbeinknochen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Ein schmaler Knochen, mit dem man Kisten oder verschlossene Truhen aufbrechen kann!\"\nVerkaufspreis:" }
entries[178682] = { ["name"] = "Atticus' Geschäftsbuch", ["text"] = "Questgegenstand\n\"Ein Geschäftsbuch, das alle Vorräte des Pakts verzeichnet.\"" }
entries[178683] = { ["name"] = "Schlingschnabels Schnabel", ["text"] = "Questgegenstand" }
