entries[178770] = { ["name"] = "Schleimiges zehrendes Organ", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+23 Ausdauer\nAnlegen: Wenn Ihr Schaden erleidet, besteht eine hohe Chance, dass Ihr Stapel von 'Unersättlich' erhaltet. Bis zu 9-mal stapelbar.\nBenutzen: Spuckt pro Stapel von 'Fressmaschine' einen Schleimhappen aus. Die Happen versuchen sofort, zu Euch zurückzukehren, wobei Euch jeder um 185 Gesundheit heilt. (20 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[178771] = { ["name"] = "Phiole der Fäulnis", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+15 [Beweglichkeit oder Stärke]\nAnlegen: Alle 5 Sek. belegt Eure nächste Nahkampffähigkeit das Ziel mit 'Verflüssigender Schlamm', was [ 19 * (10) * (1 + Vielseitigkeit)] Naturschaden im Verlauf von 30 Sek. verursacht.\n\n'Verflüssigender Schlamm' ist bis zu 3-mal stapelbar. Neue Stapel erneuern nicht die Dauer.\nVerkaufspreis:" }
entries[178772] = { ["name"] = "Säckchen der scheußlichen Diener", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+15 Intelligenz\nAnlegen: Eure Schadenszauber haben eine Chance, einen Diener aus dem Säckchen zu holen und ihn auf Euer Ziel zu hetzen. Der Diener explodiert beim Ziel und verursacht 475 Schattenschaden, der auf alle Gegner in der Nähe aufgeteilt wird.\n\nDer Schaden erhöht sich pro getroffenem Gegner, bis zu 5 Gegnern.\nVerkaufspreis:" }
