entries[178808] = { ["name"] = "Eingeweide des verdichteten Hasses", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+15 Stärke\nAnlegen: Eure Fähigkeiten haben eine sehr hohe Chance, den Effekt 'Hasserfüllter Stoß' auszulösen, die einem Gegner ( 237 * 1 ) körperlichen Schaden zufügt und Euch um 7 Gesundheit heilt. Diese Effekte sind bei weniger als 35% Gesundheit um 100% erhöht.\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\nVerkaufspreis:" }
entries[178809] = { ["name"] = "Seelenlassender Rubin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+15 Intelligenz\nBenutzen: Entzieht dem Ziel einen Teil seiner Seele, was seine Bewegungsgeschwindigkeit um 30% verringert, bis die Seele Euch erreicht. Die Seele heilt Euch sofort um 597 Gesundheit und gewährt Euch für 16 Sek. bis zu ( 70 + 86 ) kritischen Trefferwert. Ihr erhaltet mehr kritischen Trefferwert von Zielen mit niedrigerer Gesundheit. (2 Min Abklingzeit)\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\nVerkaufspreis:" }
entries[178810] = { ["name"] = "Phiole der spektralen Essenz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+15 Intelligenz\nBenutzen: Bindet für 20 Sek. eine spektrale Essenz an den Gegner, sodass die Angriffe Verbündeter diese um 30% des verursachten Schadens heilen, bis zu insgesamt 2018 Heilung.\n\nWenn die Essenz abläuft oder vorzeitig entfernt wird, platzt die verbleibende Heilung hervor und heilt bis zu 5 Verbündete innerhalb von 8 Metern. (1 Min, 30 Sek. Abklingzeit)\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\nVerkaufspreis:" }
entries[178811] = { ["name"] = "Finsterer Kodex", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+15 [Beweglichkeit oder Stärke]\nBenutzen: Beschwört eine Spektralsense, die Eurem Ziel 1550 Schattenschaden und Gegnern in einem 15 Meter großen kegelförmigen Bereich hinter dem Ziel 215 Schattenschaden zufügt. (1 Min, 30 Sek. Abklingzeit)\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\nVerkaufspreis:" }
