entries[179765] = { ["name"] = "Eichenherztunika", ["text"] = "Wird beim Aufheben gebunden\nBrust Leder\n23 Rüstung\n+16 [Beweglichkeit oder Intelligenz]\n+23 Ausdauer\n+ 10 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 22.\nHaltbarkeit 140 / 140\nSchließt Kapitel 3 Eurer Paktkampagne ab\n\nEichenherzroben (0/9)\nEichenherztunika\nEichenherzknöchelwickel\nEichenherzarmschützer\nEichenherzzierhelm\nEichenherzkniehosen\nEichenherzmantel\nEichenherzgürtel\nEichenherzarmschienen\nEichenherzcape\nEichenherzgewand\n(3) Set : Erhöht in Außengebieten der Schattenlande Eure Regeneration außerhalb des Kampfes. Der Wert erhöht sich im Land Eures Pakts.\n(5) Set : Die Dauer der Seelengestalt ist um 4 Sek. erhöht und 'Flackern' gewährt einen kurzen Geschwindigkeitsschub, solange Ihr Euch in den Schattenlanden im Freien befindet.\n(8) Set : Eure Zauber und Fähigkeiten haben eine niedrige Chance, einen Faewächter zu beschwören, der Euch für 30 Sek. schützt. Solange er lebt, erhöht er Eure Hauptwert um 60 und heilt 5 Verbündete in der Nähe regelmäßig um 450 Gesundheit.\nVerkaufspreis:" }
entries[179766] = { ["name"] = "Eichenherzknöchelwickel", ["text"] = "Wird beim Aufheben gebunden\nFüße Leder\n14 Rüstung\n+12 [Beweglichkeit oder Intelligenz]\n+18 Ausdauer\nErhöht Eure kritische Trefferwertung um + 17.\nErhöht Eure Meisterschaftswertung um + 7.\nHaltbarkeit 65 / 65\nSchließt Kapitel 5 Eurer Paktkampagne ab\n\nEichenherzroben (0/9)\nEichenherztunika\nEichenherzknöchelwickel\nEichenherzarmschützer\nEichenherzzierhelm\nEichenherzkniehosen\nEichenherzmantel\nEichenherzgürtel\nEichenherzarmschienen\nEichenherzcape\nEichenherzgewand\n(3) Set : Erhöht in Außengebieten der Schattenlande Eure Regeneration außerhalb des Kampfes. Der Wert erhöht sich im Land Eures Pakts.\n(5) Set : Die Dauer der Seelengestalt ist um 4 Sek. erhöht und 'Flackern' gewährt einen kurzen Geschwindigkeitsschub, solange Ihr Euch in den Schattenlanden im Freien befindet.\n(8) Set : Eure Zauber und Fähigkeiten haben eine niedrige Chance, einen Faewächter zu beschwören, der Euch für 30 Sek. schützt. Solange er lebt, erhöht er Eure Hauptwert um 60 und heilt 5 Verbündete in der Nähe regelmäßig um 450 Gesundheit.\nVerkaufspreis:" }
